/**
 * Lazy loader and typed TypeScript bridge for the `earthly-wasm` WebAssembly module.
 *
 * The compiled package lives in `src/lib/wasm/pkg/` (generated by
 * `./scripts/build-earthly-wasm.sh` and gitignored). Because `pkg/` may not exist
 * on a fresh checkout, the module is loaded dynamically at runtime rather than
 * statically imported so TypeScript checks and non-WASM callers never fail on
 * missing generated files.
 */

export type Position2D = [number, number]

export type VisionSupport = 'vision' | 'uncertain' | 'no-vision'

export interface GeoJsonPointGeometry {
	type: 'Point'
	coordinates: Position2D
}

export interface GeoJsonMultiPointGeometry {
	type: 'MultiPoint'
	coordinates: Position2D[]
}

export interface GeoJsonLineStringGeometry {
	type: 'LineString'
	coordinates: Position2D[]
}

export interface GeoJsonMultiLineStringGeometry {
	type: 'MultiLineString'
	coordinates: Position2D[][]
}

export interface GeoJsonPolygonGeometry {
	type: 'Polygon'
	coordinates: Position2D[][]
}

export interface GeoJsonMultiPolygonGeometry {
	type: 'MultiPolygon'
	coordinates: Position2D[][][]
}

export interface GeoJsonGeometryCollection {
	type: 'GeometryCollection'
	geometries: GeoJsonGeometry[]
}

export type GeoJsonGeometry =
	| GeoJsonPointGeometry
	| GeoJsonMultiPointGeometry
	| GeoJsonLineStringGeometry
	| GeoJsonMultiLineStringGeometry
	| GeoJsonPolygonGeometry
	| GeoJsonMultiPolygonGeometry
	| GeoJsonGeometryCollection

export interface GeoJsonFeature {
	type: 'Feature'
	geometry: GeoJsonGeometry
	properties?: Record<string, unknown> | null
	id?: string | number
}

export interface GeoJsonFeatureCollection {
	type: 'FeatureCollection'
	features: GeoJsonFeature[]
}

export type GeoJsonGeometryOrFeature = GeoJsonGeometry | GeoJsonFeature

export interface GeoJsonValidationSummary {
	featureCount: number
	geometryTypes: string[]
	bbox: [number, number, number, number] | null
	[key: string]: unknown
}

export interface SpatialImportResult {
	format: string
	title: string
	geojson: GeoJsonFeatureCollection
	featureCount: number
	warnings: string[]
}

export interface PmtilesHeaderInfo {
	[key: string]: unknown
}

export interface ProposalDiffSummary {
	[key: string]: unknown
}

export interface EarthlyWasmRawExports {
	default: (moduleOrPath?: { module_or_path: ArrayBuffer | Uint8Array | URL | string }) => Promise<unknown>
	validate_geojson_json(featureCollectionJson: string): string
	parse_pmtiles_header_json(bytes: Uint8Array): string
	parse_earthly_entity_json(rawEventJson: string): string
	diff_feature_collections_json(baseJson: string, proposedJson: string): string
	encode_geohash_str(lon: number, lat: number, precision: number): string | undefined
	simplify_line_json(coordsJson: string, toleranceMeters: number): string
	create_corridor_ring_json(coordsJson: string, totalWidthMeters: number): string
	extrude_arrow_ring_json(
		coordsJson: string,
		startWidthMeters: number,
		endWidthMeters: number,
	): string
	measure_line_meters(coordsJson: string): number
	measure_polygon_area_square_meters(ringJson: string): number
	earthly_agent_system_prompt(): string
	earthly_agent_tools_json(): string
	earthly_agent_offline_turn_json(inputJson: string): string
	import_spatial_text_json(filename: string | null | undefined, content: string): string
	export_gpx_from_geojson(geojson: string, title?: string | null): string
	export_kml_from_geojson(geojson: string, title?: string | null): string
	dissolve_lines_json(linesJson: string, toleranceMeters: number): string
	merge_to_multipart_json(geometriesJson: string): string
	explode_multipart_json(geometryJson: string): string
	parse_csv_to_geojson_json(filename: string | null | undefined, content: string): string
	export_shapefile_zip_bytes(geojson: string, title?: string | null): Uint8Array
	parse_shapefile_zip_bytes(filename: string | null | undefined, bytes: Uint8Array): string
	detect_vision_support_heuristic(model: string): string
}

export interface LoadEarthlyWasmOptions {
	/** Override JS glue URL (primarily for tests). */
	moduleUrl?: string
	/** Override `.wasm` binary URL (primarily for tests). */
	wasmUrl?: string
}

export class EarthlyWasmUnavailableError extends Error {
	override readonly cause?: unknown

	constructor(message: string, cause?: unknown) {
		super(message)
		this.name = 'EarthlyWasmUnavailableError'
		this.cause = cause
	}
}

const DEFAULT_PKG_JS_URL = new URL('./pkg/earthly_wasm.js', import.meta.url).href
const DEFAULT_PKG_WASM_URL = new URL('./pkg/earthly_wasm_bg.wasm', import.meta.url).href

let cachedExportsPromise: Promise<EarthlyWasmRawExports> | null = null
let cachedModuleUrl: string | null = null

function serializeJsonArg(value: unknown): string {
	return typeof value === 'string' ? value : JSON.stringify(value)
}

function isFileUrl(url: string): boolean {
	return url.startsWith('file://')
}

async function readLocalWasmBytes(wasmUrl: string): Promise<ArrayBuffer> {
	if (typeof Bun !== 'undefined') {
		const file = Bun.file(new URL(wasmUrl))
		if (!(await file.exists())) {
			throw new EarthlyWasmUnavailableError(
				`earthly-wasm binary not found at ${wasmUrl}. Run ./scripts/build-earthly-wasm.sh first.`,
			)
		}
		return await file.arrayBuffer()
	}
	const { readFile } = await import('node:fs/promises')
	const buf = await readFile(new URL(wasmUrl))
	return buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength)
}

async function importAndInitWasm(options?: LoadEarthlyWasmOptions): Promise<EarthlyWasmRawExports> {
	const moduleUrl = options?.moduleUrl ?? DEFAULT_PKG_JS_URL
	const wasmUrl = options?.wasmUrl ?? DEFAULT_PKG_WASM_URL

	let rawModule: EarthlyWasmRawExports
	try {
		rawModule = (await import(moduleUrl)) as EarthlyWasmRawExports
	} catch (error) {
		throw new EarthlyWasmUnavailableError(
			`earthly-wasm package is not built or could not be loaded from ${moduleUrl}. Run ./scripts/build-earthly-wasm.sh first.`,
			error,
		)
	}

	if (typeof rawModule.default !== 'function') {
		throw new EarthlyWasmUnavailableError(
			`earthly-wasm module at ${moduleUrl} is missing default init export.`,
		)
	}

	try {
		if (isFileUrl(wasmUrl)) {
			const bytes = await readLocalWasmBytes(wasmUrl)
			await rawModule.default({ module_or_path: bytes })
		} else {
			await rawModule.default({ module_or_path: wasmUrl })
		}
		return rawModule
	} catch (error) {
		if (error instanceof EarthlyWasmUnavailableError) {
			throw error
		}
		throw new EarthlyWasmUnavailableError(
			`Failed to initialize earthly-wasm binary from ${wasmUrl}. Run ./scripts/build-earthly-wasm.sh to rebuild.`,
			error,
		)
	}
}

/**
 * Lazily loads and initializes the compiled `earthly-wasm` package once per session.
 * Throws `EarthlyWasmUnavailableError` if `src/lib/wasm/pkg/` has not been built.
 */
export async function loadEarthlyWasm(
	options?: LoadEarthlyWasmOptions,
): Promise<EarthlyWasmRawExports> {
	const targetUrl = options?.moduleUrl ?? DEFAULT_PKG_JS_URL
	if (cachedExportsPromise && cachedModuleUrl === targetUrl) {
		return cachedExportsPromise
	}

	const pending = importAndInitWasm(options).catch((error) => {
		if (cachedExportsPromise === pending) {
			cachedExportsPromise = null
			cachedModuleUrl = null
		}
		throw error
	})
	cachedExportsPromise = pending
	cachedModuleUrl = targetUrl
	return pending
}

/**
 * Attempts to load `earthly-wasm`, returning `null` if the package has not been
 * built yet instead of throwing.
 */
export async function tryLoadEarthlyWasm(
	options?: LoadEarthlyWasmOptions,
): Promise<EarthlyWasmRawExports | null> {
	try {
		return await loadEarthlyWasm(options)
	} catch (error) {
		if (error instanceof EarthlyWasmUnavailableError) {
			return null
		}
		throw error
	}
}

/** Returns `true` when `earthly-wasm` is built and initializes cleanly. */
export async function isEarthlyWasmAvailable(options?: LoadEarthlyWasmOptions): Promise<boolean> {
	return (await tryLoadEarthlyWasm(options)) !== null
}

/** Clears the memoized WASM instance (for unit tests). */
export function resetEarthlyWasmCache(): void {
	cachedExportsPromise = null
	cachedModuleUrl = null
}

export async function validateGeoJson(
	featureCollection: unknown | string,
): Promise<GeoJsonValidationSummary> {
	const wasm = await loadEarthlyWasm()
	return JSON.parse(wasm.validate_geojson_json(serializeJsonArg(featureCollection))) as GeoJsonValidationSummary
}

export async function parsePmtilesHeader(bytes: Uint8Array): Promise<PmtilesHeaderInfo> {
	const wasm = await loadEarthlyWasm()
	return JSON.parse(wasm.parse_pmtiles_header_json(bytes)) as PmtilesHeaderInfo
}

